{
  "name": "opencode-task-result-guard",
  "version": "0.1.2",
  "description": "OpenCode server plugin that recovers missing and incomplete subagent task handoffs.",
  "license": "MIT",
  "author": "Jared Boynton",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jaredboynton/opencode-task-result-guard.git"
  },
  "homepage": "https://github.com/jaredboynton/opencode-task-result-guard#readme",
  "bugs": {
    "url": "https://github.com/jaredboynton/opencode-task-result-guard/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "subagent",
    "task",
    "handoff"
  ],
  "type": "module",
  "exports": {
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "package.json"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json",
    "test": "bun test",
    "test:package": "node --input-type=module -e \"import('opencode-task-result-guard/server').then((m) => { if (m.default?.id !== 'opencode-task-result-guard') process.exit(1) })\"",
    "prepack": "npm run build",
    "prepublishOnly": "bun test && npm run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.18",
    "@types/node": "^26.1.1",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  }
}
